mapper.select:
SELECT min(d) FROM (
    SELECT (created_at AT TIME ZONE #{zone})::date AS d FROM goal WHERE user_id=#{userId}
    UNION ALL SELECT (created_at AT TIME ZONE #{zone})::date FROM stage WHERE user_id=#{userId}
    UNION ALL SELECT (created_at AT TIME ZONE #{zone})::date FROM task WHERE user_id=#{userId}
    UNION ALL SELECT effective_date FROM habit_revision WHERE user_id=#{userId}
    UNION ALL SELECT (sg.started_at AT TIME ZONE #{zone})::date FROM execution_session es
        JOIN execution_segment sg ON sg.execution_id=es.id WHERE es.user_id=#{userId}
) first_dates
